import { test, expect } from '@playwright/test';

test.describe('Inline Editing on Table Row', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/your-table-page-url');
  });

  test('should allow inline editing of a table row', async ({ page }) => {
    const row = page.getByRole('row', { name: 'Row Name' });
    const editButton = row.getByRole('button', { name: 'Edit' });

    await editButton.click();

    const inputField = row.getByLabel('Editable Field');
    await inputField.fill('New Value');

    const saveButton = row.getByRole('button', { name: 'Save' });
    await saveButton.click();

    const updatedRow = page.getByRole('row', { name: 'Row Name' });
    await expect(updatedRow).toContainText('New Value');
  });

  test('should cancel inline editing of a table row', async ({ page }) => {
    const row = page.getByRole('row', { name: 'Row Name' });
    const editButton = row.getByRole('button', { name: 'Edit' });

    await editButton.click();

    const inputField = row.getByLabel('Editable Field');
    await inputField.fill('Temporary Value');

    const cancelButton = row.getByRole('button', { name: 'Cancel' });
    await cancelButton.click();

    await expect(inputField).toHaveValue('Original Value');
  });
});
